def check(condition, message):
    if not condition:
        raise ValueError(message)


def pinned(path, digest):
    path = Path(path).resolve(strict=True)
    check(identity.sha(path) == digest, "Changed pinned file: " + str(path))
    return path


def read_json(path):
    return json.loads(Path(path).read_text())


def file_record(path):
    path = Path(path).resolve(strict=True)
    return {"path": str(path), "sha256": identity.sha(path)}


def common_runtime():
    pinned(COMMON, COMMON_SHA)
    descriptor = read_json(COMMON)
    cp_file = pinned(descriptor["classpathFile"], descriptor["classpathFileSha256"])
    manifest_file = pinned(descriptor["classpathManifestFile"], descriptor["classpathManifestSha256"])
    cp = cp_file.read_text().strip()
    manifest = identity.classpath_manifest(cp)
    _, original = identity.original_identity()
    check(len(manifest) == 128 and manifest == read_json(manifest_file)
          and manifest[1:] == original and manifest[0]["sha256"] == COMMON_PREFIX_SHA
          and manifest[0]["files"] == 15 and descriptor["diagnosticOnly"] is False,
          "Common 128-entry runtime no longer matches the preserved composition")
    production = Path(manifest[descriptor["productionEntryIndex"]]["path"])
    production_files = identity.tree_files(production)
    check(len(production_files) == 2780
          and sum(name.endswith(".class") for name in production_files) == 2778,
          "Unexpected original production file/class count")
    return descriptor, cp, manifest, production_files


def run_recorded(argv, out, name, timeout):
    command = {"argv": list(map(str, argv)), "cwd": str(ROOT), "startedEpochNs": time.time_ns()}
    identity.write_new(out / (name + "-command.json"), command)
    result = {"startedEpochNs": command["startedEpochNs"], "exitCode": None, "failure": None}
    try:
        with (out / (name + ".log")).open("xb") as log:
            completed = subprocess.run(command["argv"], cwd=ROOT, stdout=log, stderr=subprocess.STDOUT,
                                       timeout=timeout, check=False)
        result["exitCode"] = completed.returncode
        check(completed.returncode == 0, name + " failed; preserved log: " + str(out / (name + ".log")))
    except BaseException as error:
        result["failure"] = {"type": type(error).__name__, "message": str(error)}
        raise
    finally:
        result["finishedEpochNs"] = time.time_ns()
        identity.write_new(out / (name + "-result.json"), result)


def verify_source_boundary(original, generated):
    check(identity.sha(original) == SELECTED_SHA, "Selected materializer source changed")
    guard = "\t\tif (plan.omittedFactorTargets[plan.aliases[target]]) {\n\t\t\treturn;\n\t\t}\n"
    marker = "/**\n * Evaluation-local last-value memo."
    before, after = Path(original).read_text(), Path(generated).read_text()
    check(after.count(guard) == 1, "Expected exactly one publication entry guard")
    check(before[before.index(marker):] == after[after.index(marker):].replace(guard, "", 1),
          "Materializer body changed outside the publication entry guard")


def compile_stage(args):
    check(args.slot_released, "Compilation requires the coordinator's exclusive slot")
    out = args.output.resolve()
    source = args.source.resolve(strict=True)
    check(identity.sha(source) == SELECTED_SHA, "Input source is not the selected original")
    base, cp, manifest, original_files = common_runtime()
    check(not out.exists(), "Refusing to overwrite an existing runtime directory")
    out.mkdir(parents=True)
    shutil.copyfile(source, out / "selected-source-preimage.java")
    tool_records = {"builder": file_record(__file__), "generator": file_record(GENERATOR),
                    "identityHelper": file_record(IDENTITY_PATH), "javac": file_record(JAVAC)}
    run_recorded([sys.executable, GENERATOR, "--source", source, "--out", out / "generated"],
                 out, "generate", 60)
    generated = out / "generated/src" / (PACKAGE + "NativeResultMaterializer.java")
    source_receipt = read_json(out / "generated/source-receipt.json")
    check(source_receipt["sourceSha256"] == SELECTED_SHA
          and source_receipt["generatedSourceSha256"] == identity.sha(generated),
          "Source generator receipt disagrees with its output")
    verify_source_boundary(source, generated)
    emitted = out / "emitted-classes"
    emitted.mkdir()
    command = [JAVAC, "--release", "25", "-g", "-proc:none", "-implicit:none", "-sourcepath", "",
               "-cp", cp, "-d", emitted, generated]
    run_recorded(command, out, "compile", 180)
    emitted_files = identity.tree_files(emitted)
    check(set(emitted_files) == PREFIX_CLASSES | NESTED_CLASSES,
          "javac emitted unexpected classes: " + str(sorted(emitted_files)))
    prefix = out / "classes"
    for name in sorted(PREFIX_CLASSES):
        target = prefix / name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(emitted / name, target)
    prefix_files = identity.tree_files(prefix)
    check(set(prefix_files) == PREFIX_CLASSES
          and all(prefix_files[name] == emitted_files[name] for name in PREFIX_CLASSES),
          "Timing prefix does not exactly contain the compiled outer and plan classes")
    frozen_cp = os.pathsep.join([str(prefix), cp])
    frozen_manifest = identity.classpath_manifest(frozen_cp)
    check(len(frozen_manifest) == 129 and frozen_manifest[1:] == manifest,
          "Compilation changed a preserved runtime entry")
    check(identity.sha(source) == SELECTED_SHA, "Selected source changed during compilation")
    for record in tool_records.values():
        pinned(record["path"], record["sha256"])
    (out / "classpath.txt").write_text(frozen_cp + "\n")
    identity.write_new(out / "classpath-manifest.json", frozen_manifest)
    identity.write_new(out / "emitted-class-files.json", emitted_files)
    identity.write_new(out / "prefix-class-files.json", prefix_files)
    identity.write_new(out / "original-production-class-files.json", original_files)
    identity.write_new(out / "compile-receipt.json", {
        "format": 1, "stage": "compiled-awaiting-validation", "compiledEpochNs": time.time_ns(),
        "baseRuntimeDescriptor": file_record(COMMON), "tools": tool_records,
        "sourcePreimage": file_record(out / "selected-source-preimage.java"),
        "generatedSource": file_record(generated), "generatedPatch": file_record(out / "generated/publication-overlay.patch"),
        "sourceGenerationReceipt": file_record(out / "generated/source-receipt.json"),
        "classpath": file_record(out / "classpath.txt"), "classpathManifest": file_record(out / "classpath-manifest.json"),
        "emittedClassFiles": file_record(out / "emitted-class-files.json"),
        "prefixClassFiles": file_record(out / "prefix-class-files.json"),
        "originalProductionClassFiles": file_record(out / "original-production-class-files.json"),
        "originalProductionEntry": manifest[base["productionEntryIndex"]],
        "prefixTreeSha256": identity.tree_digest(prefix_files),
        "materializerBodyUnchangedExceptPublicationGuard": True,
        "allEmittedFilesRetained": True, "timingPrefixClasses": sorted(PREFIX_CLASSES),
        "originalNestedClassesRetainedInRuntime": {
            name: {"original": original_files[name], "emittedButNotUsed": emitted_files[name]}
            for name in sorted(NESTED_CLASSES)},
        "productionSourceWritten": False, "timingRuntimeDescriptorCreated": False,
    })
    print(json.dumps({"compiledRuntime": str(out), "testOverlayClasses": str(prefix),
                      "emittedClasses": len(emitted_files), "prefixClasses": len(prefix_files),
                      "awaiting": "Passing focused106 and contract6 validation receipts"}))


def receipt_directory(path):
    path = path.resolve(strict=True)
    return path if path.is_dir() else path.parent


def validate_tests(path, kind, expected_files, prefix_files):
    folder = receipt_directory(path)
    receipt_path = folder / "validation-receipt.json"
    receipt = read_json(receipt_path)
    check(receipt["expectedRedEvidence"] is False and receipt["selectedProductionSourceUnchanged"] is True,
          "Need a successful unchanged-source validation: " + str(folder))
    results_path = pinned(folder / "results.json", receipt["resultsSha256"])
    production_map = pinned(folder / "production-class-files.json", receipt["productionClassFilesSha256"])
    test_map = pinned(folder / "test-class-files.json", receipt["testClassFilesSha256"])
    pinned(receipt["isolatedModulePom"], receipt["pomSha256"])
    check(read_json(folder / "tests-command.json")["exit_code"] == 0, "Test process was not successful")
    check(read_json(folder / "sources-before.json") == read_json(folder / "sources-after.json"),
          "Module source maps changed during validation")
    results = read_json(results_path)
    expected_tests, expected_reports = (106, 8) if kind == "focused" else (6, 1)
    check(results == {"classes": expected_reports, "tests": expected_tests,
                      "failures": 0, "errors": 0, "skipped": 0},
          "Wrong passing selection: " + str(results))
    reports = sorted((folder / "surefire-reports").glob("TEST-*.xml"))
    totals = dict(classes=0, tests=0, failures=0, errors=0, skipped=0)
    case_names, suite_names = [], set()
    for report in reports:
        suite = ET.parse(report).getroot()
        totals["classes"] += 1
        suite_names.add(suite.attrib["name"])
        for key in ("tests", "failures", "errors", "skipped"):
            totals[key] += int(suite.attrib.get(key, 0))
        for case in suite.findall("testcase"):
            check(case.find("failure") is None and case.find("error") is None
                  and case.find("skipped") is None, "A report contains a nonpassing case")
            case_names.append((case.attrib["classname"], case.attrib["name"]))
    check(totals == results and len(case_names) == expected_tests and len(set(case_names)) == expected_tests,
          "XML cases do not reconcile with passing results")
    if kind == "focused":
        check(suite_names == FOCUSED_CLASSES, "Focused reports have unexpected classes")
    else:
        check(suite_names == {CONTRACT_CLASS}
              and set(case_names) == {(CONTRACT_CLASS, method) for method in CONTRACT_METHODS},
              "Experimental contract case identities differ")
        archived_source = folder / "PublicationAblationContractTest.java"
        source = HERE / "test-src" / (PACKAGE + "PublicationAblationContractTest.java")
        check(identity.sha(archived_source) == identity.sha(source), "Contract source differs from tested copy")
    tested_files = identity.tree_files(folder / "classes")
    check({name: data["sha256"] for name, data in tested_files.items()} == read_json(production_map),
          "Physical tested production files changed after validation")
    check(set(tested_files) == set(expected_files), "Tested production files were added or removed")
    changed = [name for name in expected_files if expected_files[name] != tested_files[name]]
    check(set(changed) <= {"maven-config.properties"},
          "Tested production differs from timing composition: " + str(changed))
    check(all(tested_files[name] == prefix_files[name] for name in PREFIX_CLASSES),
          "Tested prefix is not the selected compiled prefix")
    check({name: data["sha256"] for name, data in identity.tree_files(folder / "test-classes").items()}
          == read_json(test_map), "Physical tested test files changed after validation")
    recorded_files = [receipt_path, results_path, production_map, test_map,
                      folder / "sources-before.json", folder / "sources-after.json", folder / "test-cases.json",
                      folder / "tests-command.json", folder / "pom.xml", *reports]
    if kind == "contracts":
        recorded_files.append(folder / "PublicationAblationContractTest.java")
    return {
        "kind": kind, "directory": str(folder), "results": results,
        "files": [file_record(p) for p in recorded_files],
        "all2778ClassFilesMatchFrozenComposition": True,
        "twoOverlayClassesMatchExactly": True,
        "originalFactorMemoAndFactorPageBytesPreserved": True,
        "caseIdentities": [list(item) for item in sorted(case_names)],
        "allowedGeneratedResourceDifferences": {
            name: {"timingRuntime": expected_files[name], "testedRuntime": tested_files[name],
                   "reason": "Generated Maven configuration resource differs after the fresh build; no class bytes differ."}
            for name in changed},
    }


def freeze_stage(args):
    out = args.runtime.resolve(strict=True)
    check(not (out / "runtime-descriptor.json").exists(), "Runtime is already frozen")
    compile_receipt = read_json(out / "compile-receipt.json")
    check(compile_receipt["format"] == 1 and compile_receipt["stage"] == "compiled-awaiting-validation",
          "No successful compilation receipt")
    for value in compile_receipt.values():
        if isinstance(value, dict) and set(value) == {"path", "sha256"}:
            pinned(value["path"], value["sha256"])
    for value in compile_receipt["tools"].values():
        pinned(value["path"], value["sha256"])
    base, cp, manifest, original_files = common_runtime()
    prefix_files = identity.tree_files(out / "classes")
    check(set(prefix_files) == PREFIX_CLASSES and prefix_files == read_json(out / "prefix-class-files.json"),
          "Compiled prefix changed")
    check(identity.tree_files(out / "emitted-classes") == read_json(out / "emitted-class-files.json"),
          "Preserved compiler output changed")
    check(original_files == read_json(out / "original-production-class-files.json"),
          "Original production bytes changed")
    generated = Path(compile_receipt["generatedSource"]["path"])
    verify_source_boundary(SELECTED_SOURCE, generated)
    verify_source_boundary(out / "selected-source-preimage.java", generated)
    expected_files = {**original_files, **prefix_files}
    validations = [validate_tests(args.focused_validation, "focused", expected_files, prefix_files),
                   validate_tests(args.contract_validation, "contracts", expected_files, prefix_files)]
    tested_maps = [read_json(Path(v["directory"]) / "sources-after.json") for v in validations]
    check(tested_maps[0] == tested_maps[1], "Focused and contract runs used different module sources")
    current_sources = {p.relative_to(ROOT / "core/sail/lmdb/src").as_posix(): identity.sha(p)
                       for p in sorted((ROOT / "core/sail/lmdb/src").rglob("*")) if p.is_file()}
    check(tested_maps[0] == current_sources, "Current module sources differ from validated source maps")
    frozen_cp = (out / "classpath.txt").read_text().strip()
    frozen_manifest = identity.classpath_manifest(frozen_cp)
    check(frozen_cp == os.pathsep.join([str(out / "classes"), cp])
          and frozen_manifest == read_json(out / "classpath-manifest.json")
          and len(frozen_manifest) == 129 and frozen_manifest[1:] == manifest,
          "Frozen classpath changed or contains unexpected entries")
    validation_file = out / "validation.json"
    identity.write_new(validation_file, {
        "format": 1, "passed": True, "tests": 112, "failures": 0, "errors": 0, "skipped": 0,
        "records": validations, "validatedModuleSourcesEqualCurrent": True,
        "timingPrefixClassFiles": prefix_files,
        "unchangedOriginalClassFiles": 2776, "replacedOuterAndPlanClassFiles": 2,
        "materializerBodyUnchangedExceptPublicationGuard": True,
        "experimentalMetadataAccounting": "One per-plan boolean array and reference are common to all arms and outside the existing query ledger.",
    })
    descriptor = {
        "format": 1, "name": "publication-omission-original-pages", "diagnosticOnly": False,
        "sourceIdentity": base["sourceIdentity"] + "+publication-omission-sha256-" + identity.sha(generated),
        "classpathEntryCount": 129, "prefixEntryCount": 1, "prefixClasses": sorted(PREFIX_CLASSES),
        "originalNestedClassesUsed": sorted(NESTED_CLASSES), "allArmsShareCompiledRuntime": True,
        "selectedProductionSourceSha256": SELECTED_SHA,
        "productionEntryIndex": base["productionEntryIndex"] + 1,
        "noProductionPromotion": True,
    }
    for key, path in (
        ("classpathFile", out / "classpath.txt"),
        ("classpathManifestFile", out / "classpath-manifest.json"),
        ("baseRuntimeDescriptorFile", COMMON),
        ("overlaySourceFile", generated),
        ("overlayPatchFile", out / "generated/publication-overlay.patch"),
        ("validationFile", validation_file),
        ("compileReceiptFile", out / "compile-receipt.json"),
        ("emittedClassFilesFile", out / "emitted-class-files.json"),
        ("prefixClassFilesFile", out / "prefix-class-files.json"),
        ("sourceGenerationFile", out / "generated/source-receipt.json"),
        ("runtimeBuilderFile", Path(__file__)),
        ("sourceGeneratorFile", GENERATOR),
    ):
        descriptor[key] = str(path.resolve())
        descriptor[key + "Sha256"] = identity.sha(path)
    identity.write_new(out / "runtime-descriptor.json", descriptor)
    print(json.dumps({"frozenRuntimeDescriptor": str(out / "runtime-descriptor.json"),
                      "sha256": identity.sha(out / "runtime-descriptor.json"),
                      "tests": 112, "prefixClasses": 2, "preservedOtherOriginalClasses": 2776,
                      "benchmarkJvmsLaunched": 0}))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    stages = parser.add_subparsers(dest="stage", required=True)
    compile_parser = stages.add_parser("compile", help="Generate and compile, but do not freeze a timing descriptor")
    compile_parser.add_argument("--source", type=Path, default=SELECTED_SOURCE)
    compile_parser.add_argument("--output", type=Path, default=PHASE / "runtimes/publication-overlay-v1")
    compile_parser.add_argument("--slot-released", action="store_true")
    freeze_parser = stages.add_parser("freeze", help="Verify passing isolated tests and freeze the exact runtime")
    freeze_parser.add_argument("--runtime", type=Path, required=True)
    freeze_parser.add_argument("--focused-validation", type=Path, required=True,
                               help="Passing focused106 validation directory or receipt file")
    freeze_parser.add_argument("--contract-validation", type=Path, required=True,
                               help="Passing contract6 validation directory or receipt file")
    args = parser.parse_args()
    if args.stage == "compile":
        compile_stage(args)
    else:
        freeze_stage(args)


if __name__ == "__main__":
    main()
